import React, { useRef, useState } from 'react';

const GENRES = ['Hoạt Hình', 'Hành Động', 'Viễn Tưởng', 'Kinh Dị'];
const MAX_IMAGE_SIZE = 2 * 1024 * 1024;
const ACCEPTED_IMAGE_TYPES = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];

const EMPTY_FORM = {
  title: '',
  duration: '',
  genre: 'Hoạt Hình',
  image_url: '',
  description: '',
  rating: '0/5 ⭐',
  viewers: '0',
  ticket_price: '85000',
};

const digitsOnly = (value) => String(value ?? '').replace(/\D/g, '');

const parseTicketPrice = (value) => {
  const digits = digitsOnly(value);
  return digits ? Number(digits) : 0;
};

function MovieManagement({
  movies,
  showtimes = [],
  onCreateMovie,
  onUpdateMovie,
  onDeleteMovie,
  onBack,
}) {
  const [searchTerm, setSearchTerm] = useState('');
  const [mode, setMode] = useState('list');
  const [form, setForm] = useState(EMPTY_FORM);
  const [editingId, setEditingId] = useState(null);
  const [viewMovie, setViewMovie] = useState(null);
  const [formError, setFormError] = useState('');
  const [priceDrafts, setPriceDrafts] = useState({});
  const fileInputRef = useRef(null);

  const filteredMovies = movies.filter((movie) =>
    movie.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getShowtimeCount = (movieId) =>
    showtimes.filter((st) => st.movie_id === movieId).length;

  const resetForm = () => {
    setForm(EMPTY_FORM);
    setEditingId(null);
    setFormError('');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const openCreate = () => {
    resetForm();
    setMode('form');
  };

  const openEdit = (movie) => {
    setEditingId(movie.id);
    setForm({
      title: movie.title,
      duration: String(movie.duration),
      genre: movie.genre,
      image_url: movie.image_url,
      description: movie.description,
      rating: movie.rating || '0/5 ⭐',
      viewers: String(movie.viewers ?? 0),
      ticket_price: String(movie.ticket_price ?? 85000),
    });
    setFormError('');
    setMode('form');
  };

  const openView = (movie) => {
    setViewMovie(movie);
    setMode('detail');
  };

  const validateForm = () => {
    if (!form.title.trim()) return 'Vui lòng nhập tên phim.';
    if (!form.duration || Number(form.duration) <= 0) return 'Thời lượng phải lớn hơn 0.';
    if (!form.image_url.trim()) return 'Vui lòng tải ảnh poster từ máy.';
    if (!form.description.trim()) return 'Vui lòng nhập mô tả phim.';
    if (parseTicketPrice(form.ticket_price) <= 0) return 'Giá vé phải lớn hơn 0.';
    return '';
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const error = validateForm();
    if (error) {
      setFormError(error);
      return;
    }

    const payload = {
      title: form.title.trim(),
      duration: Number(form.duration),
      genre: form.genre,
      image_url: form.image_url.trim(),
      description: form.description.trim(),
      rating: form.rating.trim() || '0/5 ⭐',
      viewers: Number(form.viewers) || 0,
      ticket_price: parseTicketPrice(form.ticket_price),
    };

    if (editingId !== null) {
      onUpdateMovie({ ...payload, id: editingId });
    } else {
      const nextId =
        movies.length === 0
          ? 1
          : Math.max(...movies.map((m) => Number(m.id))) + 1;
      onCreateMovie({ ...payload, id: nextId });
    }

    resetForm();
    setMode('list');
  };

  const handleDelete = (movie) => {
    const stCount = getShowtimeCount(movie.id);
    const msg =
      stCount > 0
        ? `Phim "${movie.title}" có ${stCount} suất chiếu. Xóa phim có thể ảnh hưởng dữ liệu liên quan. Bạn có chắc muốn xóa?`
        : `Bạn có chắc muốn xóa phim "${movie.title}"?`;
    if (!window.confirm(msg)) return;
    onDeleteMovie(movie.id);
    if (viewMovie?.id === movie.id) {
      setViewMovie(null);
      setMode('list');
    }
  };

  const handleFormChange = (field, value) => {
    setForm((prev) => ({ ...prev, [field]: value }));
    if (formError) setFormError('');
  };

  const handleTicketPriceChange = (value) => {
    handleFormChange('ticket_price', digitsOnly(value));
  };

  const getListPriceValue = (movie) =>
    priceDrafts[movie.id] !== undefined
      ? priceDrafts[movie.id]
      : digitsOnly(movie.ticket_price);

  const handleListPriceChange = (movieId, value) => {
    setPriceDrafts((prev) => ({ ...prev, [movieId]: digitsOnly(value) }));
  };

  const commitListPrice = (movie) => {
    const raw =
      priceDrafts[movie.id] !== undefined
        ? priceDrafts[movie.id]
        : digitsOnly(movie.ticket_price);
    const price = parseTicketPrice(raw);

    setPriceDrafts((prev) => {
      const next = { ...prev };
      delete next[movie.id];
      return next;
    });

    if (price > 0 && price !== movie.ticket_price) {
      onUpdateMovie({ ...movie, ticket_price: price });
    }
  };

  const handleImageUpload = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!ACCEPTED_IMAGE_TYPES.includes(file.type)) {
      setFormError('Chỉ chấp nhận ảnh JPG, PNG, WebP hoặc GIF.');
      e.target.value = '';
      return;
    }
    if (file.size > MAX_IMAGE_SIZE) {
      setFormError('Ảnh tối đa 2MB. Vui lòng chọn file nhỏ hơn.');
      e.target.value = '';
      return;
    }

    const reader = new FileReader();
    reader.onload = () => {
      handleFormChange('image_url', reader.result);
    };
    reader.onerror = () => {
      setFormError('Không đọc được file ảnh. Vui lòng thử lại.');
    };
    reader.readAsDataURL(file);
  };

  const clearPoster = () => {
    handleFormChange('image_url', '');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div>
      <div className="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-4 pb-2 border-bottom">
        <div>
          <h2 className="fw-bold text-uppercase m-0" style={{ color: '#7c3aed', letterSpacing: '0.5px' }}>
            Quản Lý Phim
          </h2>
        </div>
        <div className="d-flex flex-wrap gap-2">
          {mode === 'list' && (
            <button
              type="button"
              className="btn fw-bold px-4 py-2 rounded-pill text-white border-0"
              style={{ background: 'linear-gradient(135deg, #7c3aed 0%, #a855f7 100%)', boxShadow: '0 10px 30px rgba(124,58,237,0.12)' }}
              onClick={openCreate}
            >
              ➕ Thêm phim mới
            </button>
          )}
          <button
            type="button"
            className="btn fw-bold px-4 py-2 rounded-pill border-0"
            style={{ background: '#f3f4f6', color: '#374151' }}
            onClick={() => {
              if (mode === 'list') onBack();
              else {
                resetForm();
                setViewMovie(null);
                setMode('list');
              }
            }}
          >
            {mode === 'list' ? '⬅ Về trang chủ' : '⬅ Quay lại danh sách'}
          </button>
        </div>
      </div>

      {mode === 'list' && (
        <>
          <div
            className="card p-3 shadow-sm border-0 mb-4"
            style={{ backgroundColor: '#faf5ff', borderRadius: '16px', border: '1px solid rgba(124,58,237,0.06)' }}
          >
            <label className="form-label fw-bold text-secondary small mb-1">Tìm kiếm phim</label>
            <input
              type="text"
              className="form-control border-0 shadow-sm"
              style={{ borderRadius: '10px', padding: '10px 15px' }}
              placeholder="Nhập tên phim..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>

          <div className="table-responsive card shadow-sm border-0" style={{ borderRadius: '16px', overflow: 'hidden' }}>
            <table className="table table-hover align-middle mb-0">
              <thead style={{ backgroundColor: '#ede9fe' }}>
                <tr>
                  <th className="ps-3">#</th>
                  <th>Poster</th>
                  <th>Tên phim</th>
                  <th>Thể loại</th>
                  <th>Thời lượng</th>
                  <th>Giá vé</th>
                  <th>Lượt xem</th>
                  <th>Suất chiếu</th>
                  <th className="text-end pe-3">Thao tác</th>
                </tr>
              </thead>
              <tbody>
                {filteredMovies.length === 0 ? (
                  <tr>
                    <td colSpan="9" className="text-center text-secondary py-5">
                      Không có phim nào.
                    </td>
                  </tr>
                ) : (
                  filteredMovies.map((movie, index) => (
                    <tr key={movie.id}>
                      <td className="ps-3 fw-bold text-secondary">{index + 1}</td>
                      <td>
                        <img
                          src={movie.image_url}
                          alt={movie.title}
                          style={{ width: 48, height: 64, objectFit: 'cover', borderRadius: 8 }}
                        />
                      </td>
                      <td className="fw-bold" style={{ maxWidth: 220 }}>
                        {movie.title}
                      </td>
                      <td>
                        <span
                          className="badge px-2 py-1"
                          style={{ backgroundColor: '#ede9fe', color: '#7c3aed' }}
                        >
                          {formatGenre(movie.genre)}
                        </span>
                      </td>
                      <td>{movie.duration} phút</td>
                      <td style={{ minWidth: 130 }}>
                        <div className="d-flex align-items-center gap-1">
                          <input
                            type="text"
                            inputMode="numeric"
                            className="form-control form-control-sm fw-bold"
                            style={{ width: 100, borderRadius: 8, color: '#7c3aed' }}
                            value={getListPriceValue(movie)}
                            onChange={(e) => handleListPriceChange(movie.id, e.target.value)}
                            onBlur={() => commitListPrice(movie)}
                            onKeyDown={(e) => {
                              if (e.key === 'Enter') e.currentTarget.blur();
                            }}
                            placeholder="85000"
                            aria-label={`Giá vé ${movie.title}`}
                          />
                          <span className="small text-muted">đ</span>
                        </div>
                      </td>
                      <td>{Number(movie.viewers).toLocaleString()}</td>
                      <td>{getShowtimeCount(movie.id)}</td>
                      <td className="text-end pe-3">
                        <div className="d-flex justify-content-end flex-wrap gap-1">
                          <button
                            type="button"
                            className="btn btn-sm fw-bold"
                            style={{ background: '#e0e7ff', color: '#4338ca', borderRadius: 8 }}
                            onClick={() => openView(movie)}
                            title="Xem chi tiết"
                          >
                            👁 Xem
                          </button>
                          <button
                            type="button"
                            className="btn btn-sm fw-bold"
                            style={{ background: '#fef3c7', color: '#b45309', borderRadius: 8 }}
                            onClick={() => openEdit(movie)}
                            title="Sửa phim"
                          >
                            ✏️ Sửa
                          </button>
                          <button
                            type="button"
                            className="btn btn-sm fw-bold text-white"
                            style={{ background: '#ef4444', borderRadius: 8 }}
                            onClick={() => handleDelete(movie)}
                            title="Xóa phim"
                          >
                            🗑 Xóa
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
          <p className="text-secondary small mt-3 mb-0">
            Tổng cộng: <strong>{filteredMovies.length}</strong> / {movies.length} phim
          </p>
        </>
      )}

      {mode === 'detail' && viewMovie && (
        <div className="card border-0 shadow-sm overflow-hidden" style={{ borderRadius: '16px' }}>
          <div className="row g-0">
            <div className="col-md-4">
              <img
                src={viewMovie.image_url}
                alt={viewMovie.title}
                className="w-100 h-100"
                style={{ minHeight: 320, objectFit: 'cover' }}
              />
            </div>
            <div className="col-md-8 p-4 bg-white">
              <h3 className="fw-bold mb-2">{viewMovie.title}</h3>
              <div className="d-flex flex-wrap gap-2 mb-3">
                <span className="badge px-3 py-2" style={{ backgroundColor: '#ede9fe', color: '#7c3aed' }}>
                  🏷 {formatGenre(viewMovie.genre)}
                </span>
                <span className="badge bg-light text-dark px-3 py-2">⏱ {viewMovie.duration} phút</span>
                <span className="badge px-3 py-2" style={{ backgroundColor: '#ede9fe', color: '#7c3aed' }}>
                  🎟 {Number(viewMovie.ticket_price || 0).toLocaleString()}đ
                </span>
                <span className="badge bg-light text-dark px-3 py-2">⭐ {viewMovie.rating}</span>
                <span className="badge bg-light text-dark px-3 py-2">
                  👁 {Number(viewMovie.viewers).toLocaleString()} lượt xem
                </span>
              </div>
              <p className="text-secondary" style={{ lineHeight: 1.6 }}>
                {viewMovie.description}
              </p>
              <p className="small text-muted mb-0">Mã phim: #{viewMovie.id}</p>
              <div className="d-flex gap-2 mt-4">
                <button
                  type="button"
                  className="btn fw-bold text-white border-0"
                  style={{ background: 'linear-gradient(135deg, #7c3aed 0%, #a855f7 100%)' }}
                  onClick={() => openEdit(viewMovie)}
                >
                  ✏️ Chỉnh sửa
                </button>
                <button
                  type="button"
                  className="btn fw-bold text-white border-0"
                  style={{ background: '#ef4444' }}
                  onClick={() => handleDelete(viewMovie)}
                >
                  🗑 Xóa phim
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {mode === 'form' && (
        <div
          className="card p-4 shadow-sm border-0 mx-auto"
          style={{ maxWidth: 640, borderRadius: '16px', backgroundColor: '#faf5ff' }}
        >
          <h4 className="fw-bold mb-4" style={{ color: '#7c3aed' }}>
            {editingId !== null ? '✏️ Cập nhật phim' : '➕ Thêm phim mới'}
          </h4>

          {formError && (
            <div className="alert alert-danger py-2 small mb-3" role="alert">
              {formError}
            </div>
          )}

          <form onSubmit={handleSubmit}>
            <div className="mb-3">
              <label className="form-label fw-bold small text-secondary">Tên phim *</label>
              <input
                type="text"
                className="form-control"
                style={{ borderRadius: '10px' }}
                value={form.title}
                onChange={(e) => handleFormChange('title', e.target.value)}
                placeholder="Nhập tên phim"
              />
            </div>

            <div className="row g-3">
              <div className="col-md-6">
                <label className="form-label fw-bold small text-secondary">Thể loại *</label>
                <select
                  className="form-select"
                  style={{ borderRadius: '10px' }}
                  value={form.genre}
                  onChange={(e) => handleFormChange('genre', e.target.value)}
                >
                  {GENRES.map((g) => (
                    <option key={g} value={g}>
                      {g}
                    </option>
                  ))}
                </select>
              </div>
              <div className="col-md-6">
                <label className="form-label fw-bold small text-secondary">Thời lượng (phút) *</label>
                <input
                  type="number"
                  min="1"
                  className="form-control"
                  style={{ borderRadius: '10px' }}
                  value={form.duration}
                  onChange={(e) => handleFormChange('duration', e.target.value)}
                />
              </div>
            </div>

            <div className="mb-3 mt-3">
              <label className="form-label fw-bold small text-secondary">Giá vé (VNĐ) *</label>
              <input
                type="text"
                inputMode="numeric"
                className="form-control"
                style={{ borderRadius: '10px' }}
                value={form.ticket_price}
                onChange={(e) => handleTicketPriceChange(e.target.value)}
                placeholder="Nhập giá, ví dụ: 85000 hoặc 85.000"
              />
              <p className="text-muted small mt-1 mb-0">
                Gõ số bằng bàn phím — có thể nhập 85000 hoặc 85.000
                {form.ticket_price ? (
                  <span className="ms-1 fw-bold" style={{ color: '#7c3aed' }}>
                    (= {parseTicketPrice(form.ticket_price).toLocaleString()}đ)
                  </span>
                ) : null}
              </p>
            </div>

            <div className="mb-3">
              <label className="form-label fw-bold small text-secondary">Ảnh poster *</label>
              <input
                ref={fileInputRef}
                type="file"
                className="form-control"
                style={{ borderRadius: '10px' }}
                accept="image/jpeg,image/png,image/webp,image/gif"
                onChange={handleImageUpload}
              />
              <p className="text-muted small mt-1 mb-0">
                Chọn ảnh từ máy (JPG, PNG, WebP, GIF — tối đa 2MB)
              </p>
              {form.image_url && (
                <div className="mt-3">
                  <img
                    src={form.image_url}
                    alt="Xem trước poster"
                    className="rounded shadow-sm"
                    style={{ maxHeight: 160, maxWidth: '100%', objectFit: 'cover' }}
                  />
                  <button
                    type="button"
                    className="btn btn-sm fw-bold mt-2"
                    style={{ background: '#fee2e2', color: '#b91c1c' }}
                    onClick={clearPoster}
                  >
                    🗑 Xóa ảnh đã chọn
                  </button>
                </div>
              )}
            </div>

            <div className="mb-3">
              <label className="form-label fw-bold small text-secondary">Mô tả *</label>
              <textarea
                className="form-control"
                rows={4}
                style={{ borderRadius: '10px' }}
                value={form.description}
                onChange={(e) => handleFormChange('description', e.target.value)}
                placeholder="Mô tả nội dung phim..."
              />
            </div>

            <div className="row g-3">
              <div className="col-md-6">
                <label className="form-label fw-bold small text-secondary">Đánh giá</label>
                <input
                  type="text"
                  className="form-control"
                  style={{ borderRadius: '10px' }}
                  value={form.rating}
                  onChange={(e) => handleFormChange('rating', e.target.value)}
                  placeholder="4.8/5 ⭐"
                />
              </div>
              <div className="col-md-6">
                <label className="form-label fw-bold small text-secondary">Lượt xem</label>
                <input
                  type="number"
                  min="0"
                  className="form-control"
                  style={{ borderRadius: '10px' }}
                  value={form.viewers}
                  onChange={(e) => handleFormChange('viewers', e.target.value)}
                />
              </div>
            </div>

            <div className="d-flex gap-2 mt-4">
              <button
                type="submit"
                className="btn flex-grow-1 fw-bold text-white border-0 py-2"
                style={{ background: 'linear-gradient(135deg, #7c3aed 0%, #a855f7 100%)', borderRadius: '12px' }}
              >
                {editingId !== null ? '💾 Lưu thay đổi' : '✅ Thêm phim'}
              </button>
              <button
                type="button"
                className="btn fw-bold py-2 px-4"
                style={{ background: '#f3f4f6', borderRadius: '12px' }}
                onClick={() => {
                  resetForm();
                  setMode('list');
                }}
              >
                Hủy
              </button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
}

export default MovieManagement;
